typedef __int128 i128;
string str(i128 v) {
    if (v == 0) return "0";
    bool neg = v < 0;
    string s;
    while (v != 0) { int d = (int)(v % 10); s += char('0' + (d < 0 ? -d : d)); v /= 10; }
    if (neg) s += '-';
    return string(s.rbegin(), s.rend());
