import java.math.BigInteger;
import java.util.*;

public class Main {
    static BigInteger big(long v) { return BigInteger.valueOf(v); }

    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long remaining = r.nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        Arrays.sort(a);  // ascending; the k-th largest is a[n-1-k]
        long minimum = a[0], h = a[n - 1];
        BigInteger answer = BigInteger.ZERO;
        for (int count = 1; count < n; count++) {
            // lower the top `count` items from h to the next height, in rounds of `count` steps
            long lower = a[n - 1 - count];
            long take = Math.min(remaining, count * (h - lower)), q = take / count, rem = take % count;
            answer = answer.add(big(count * q).multiply(big(2 * h - q + 1)).shiftRight(1))
                .add(big(rem).multiply(big(h - q)))
                .add(big(minimum).multiply(big(take)));
            remaining -= take;
            if (remaining == 0) { System.out.println(answer); return; }
            h = lower;
        }
        // all n values equal h: the minimum also drops after each round's first step
        long q = remaining / n, rem = remaining % n;
        BigInteger bq = big(q);
        BigInteger inner = bq.multiply(big(h)).subtract(bq.multiply(big(q - 1)).shiftRight(1));
        answer = answer.add(big(2L * n).multiply(inner)).subtract(bq.multiply(big(n - 1)));
        if (rem > 0) answer = answer.add(big(2 * rem).multiply(big(h - q))).subtract(big(rem - 1));
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"slices"
)

func main() {
	n, remaining := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	slices.Sort(a)
	slices.Reverse(a)
	minimum, h := a[n-1], a[0]
	b := func(v int) *big.Int { return big.NewInt(int64(v)) }
	answer := new(big.Int)
	for count := 1; count < n; count++ {
		// lower the top `count` items from h to the next height, in rounds of `count` steps
		lower := a[count]
		take := min(remaining, count*(h-lower))
		q, r := take/count, take%count
		t := new(big.Int).Mul(b(count*q), b(2*h-q+1))
		answer.Add(answer, t.Rsh(t, 1))
		answer.Add(answer, new(big.Int).Mul(b(r), b(h-q)))
		answer.Add(answer, new(big.Int).Mul(b(minimum), b(take)))
		remaining -= take
		if remaining == 0 {
			fmt.Println(answer)
			return
		}
		h = lower
	}
	// all n values equal h: the minimum also drops after each round's first step
	q, r := remaining/n, remaining%n
	inner := new(big.Int).Mul(b(q), b(h))
	half := new(big.Int).Mul(b(q), b(q-1))
	inner.Sub(inner, half.Rsh(half, 1))
	answer.Add(answer, inner.Mul(inner, b(2*n)))
	answer.Sub(answer, new(big.Int).Mul(b(q), b(n-1)))
	if r > 0 {
		answer.Add(answer, new(big.Int).Mul(b(2*r), b(h-q)))
		answer.Sub(answer, b(r-1))
	}
	fmt.Println(answer)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
